    name: 'support_page_url',
    nullable: true,
    length: 1024,
    default: undefined,
  })
  public supportPageUrl: string;

  @Column({ name: 'is_validated', type: 'bit', default: () => '1' })
  public isValidated: boolean;

  public hasNoChildren(): boolean {
    return this.children && this.children.length === 0;
  }
}

