import { Controller, Get, Query } from '@nestjs/common';
import { ApiOperation, ApiQuery, ApiResponse } from '@nestjs/swagger';
import { AppPageListService } from './app-page-list.service';
import { AppLogger } from '@/common/logger/app-logger';

@Controller('app-page-list')
export class AppPageListController {
  public constructor(private readonly appPageListService: AppPageListService) {}

  @Get('find-support-url')
  @ApiOperation({ summary: 'Get support URL by route path' })
  @ApiQuery({
    name: 'path',
    type: String,
    description: 'The route path to resolve support URL for',
    required: true,
  })
  @ApiResponse({
    status: 200,
    description: 'Support URL found',
    schema: {
      example: { supportUrl: 'https://example.com/support' },
    },
  })
  @ApiResponse({
    status: 500,
    description: 'Internal server error',
  })
  public async findSupportUrlByRoute(
    @Query('path') path: string,
  ): Promise<{ supportUrl: string | null } | undefined> {
    try {
      const supportUrl = await this.appPageListService.getSupportUrl(path);
      return { supportUrl };
    } catch (error) {
      AppLogger.error('Error resolving support URL:', error);
      return undefined;
    }
  }
}

