import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppPagesList } from './app-page-list.entity';

@Injectable()
export class AppPageListService {
  public constructor(
    @InjectRepository(AppPagesList)
    private readonly appPageListRepository: Repository<AppPagesList>,
  ) {}

  public async getSupportUrl(currentPath: string): Promise<string | null> {
    const repo = this.appPageListRepository;

    if (currentPath === '/downtime-ui') {
      const exact = await repo.findOne({
        where: { link: '/downtime-ui' },
        select: ['supportPageUrl'],
      });
      return exact?.supportPageUrl ?? null;
    }

    const allPages = await repo.find({ select: ['link', 'supportPageUrl'] });

    const matches = allPages.filter((page) => currentPath.includes(page.link));

    if (matches.length === 1) {
      return matches[0].supportPageUrl ?? null;
    }
    if (matches.length > 1) {
      const sortedMatches = [...matches].sort(
        (a, b) => b.link.length - a.link.length,
      );
      const bestMatch = sortedMatches[0];

      return bestMatch?.supportPageUrl ?? null;
    }

    return null;
  }
}

