import {
  Injectable,
  NotFoundException,
  InternalServerErrorException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { GetByPlantDto } from './dtos/get-by-plant.dto';
import { GetByUserGroupDto } from './dtos/get-by-user-group.dto';
import { GetGroupNamesDto } from './dtos/get-group-names.dto';
import { FilterConfig } from './filter-config.entity';

@Injectable()
export class FilterConfigService {
  public constructor(
    @InjectRepository(FilterConfig)
    private readonly filterConfigRepository: Repository<FilterConfig>,
  ) {}

  public async findByPlant(dto: GetByPlantDto): Promise<Array<FilterConfig>> {
    try {
      return await this.filterConfigRepository
        .createQueryBuilder('config')
        .where('config.plant = :plant', { plant: dto.plant })
        .andWhere('config.appName = :appName', { appName: dto.appName })
        .andWhere('config.userId IS NULL')
        .getMany();
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve filters by plant',
      );
    }
  }

  public async findGroupNames(dto: GetGroupNamesDto): Promise<Array<string>> {
    try {
      const groups = await this.filterConfigRepository.find({
        where: {
          userId: dto.userId,
          plant: dto.plant,
          appName: dto.appName,
        },
        select: ['groupName'],
        order: { groupName: 'ASC' },
      });

      return groups.map((g) => g.groupName);
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve group names for the user',
      );
    }
  }

  public async create(data: FilterConfig): Promise<FilterConfig> {
    try {
      const entity = this.filterConfigRepository.create(data);
      return await this.filterConfigRepository.save(entity);
    } catch {
      throw new InternalServerErrorException(
        'Failed to create filter configuration',
      );
    }
  }

  public async update(id: number, data: FilterConfig): Promise<FilterConfig> {
    try {
      const existing = await this.filterConfigRepository.findOneBy({ id });

      if (!existing) {
        throw new NotFoundException(`FilterConfig #${id} not found`);
      }

      const updated = Object.assign(existing, data);
      return await this.filterConfigRepository.save(updated);
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to update FilterConfig #${id}`,
      );
    }
  }

  public async delete(id: number): Promise<void> {
    try {
      const result = await this.filterConfigRepository.delete(id);

      if (result.affected === 0) {
        throw new NotFoundException(`FilterConfig #${id} not found`);
      }
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to delete FilterConfig #${id}`,
      );
    }
  }

  public async findByUserAndGroup(
    dto: GetByUserGroupDto,
  ): Promise<FilterConfig | undefined> {
    try {
      const filter = await this.filterConfigRepository.findOne({
        where: {
          plant: dto.plant,
          groupName: dto.groupName,
          appName: dto.appName,
        },
      });
      return filter ?? undefined;
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve filter by user group',
      );
    }
  }
}

