import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { User } from 'src/user/user.entity';
import { Repository } from 'typeorm';
import { HomepageShortcutDto } from './dtos/homepage-shortcut.dto';
import { HomepageShortcut } from './entities/homepage-shortcut.entity';

@Injectable()
export class HomepageShortcutService {
  public constructor(
    @InjectRepository(HomepageShortcut)
    private readonly shortcutRepo: Repository<HomepageShortcut>,

    @InjectRepository(User)
    private readonly userRepo: Repository<User>,
  ) {}

  public async create(dto: HomepageShortcutDto): Promise<HomepageShortcut> {
    const user = await this.userRepo.findOne({ where: { userId: dto.userId } });
    if (!user) throw new NotFoundException('User not found');

    const shortcut = this.shortcutRepo.create({
      user,
      pageId: dto.pageId,
      position: dto.position,
    });

    return this.shortcutRepo.save(shortcut);
  }

  public async findByUser(userId: number): Promise<Array<HomepageShortcut>> {
    return this.shortcutRepo.find({
      where: { user: { userId } },
      order: { position: 'ASC' },
    });
  }

  public async update(
    id: number,
    dto: HomepageShortcutDto,
  ): Promise<HomepageShortcut> {
    const shortcut = await this.shortcutRepo.findOne({
      where: { shortcutId: id },
    });
    if (!shortcut) throw new NotFoundException('Shortcut not found');

    shortcut.pageId = dto.pageId ?? shortcut.pageId;
    shortcut.position = dto.position ?? shortcut.position;

    return this.shortcutRepo.save(shortcut);
  }

  public async remove(id: number): Promise<void> {
    const shortcut = await this.shortcutRepo.findOne({
      where: { shortcutId: id },
    });
    if (!shortcut) throw new NotFoundException('Shortcut not found');

    await this.shortcutRepo.remove(shortcut);
  }
}

