/**
 *
 * @param role role name
 * @param permissions list of app names (permissions) to check for the role
 * @returns SQL query string to select the specified permissions for the role if they do not already exist
 */
function buildPermissionSelect(
  role: string,
  permissions: Array<string>,
): string {
  return permissions
    .map(
      (appName) => `
        SELECT r.role_id, '${appName}' AS app_name, GETDATE() AS created_at, GETDATE() AS updated_at
        FROM role r
        WHERE r.role_name = '${role}'
          AND NOT EXISTS (
            SELECT 1
            FROM permission p
            WHERE p.role_id = r.role_id
              AND p.app_name = '${appName}'
          )
      `,
    )
    .join(' UNION ALL ');
}

/**
 *
 * @param role role name
 * @param permissions list of app names (permissions) to delete for the role
 * @returns SQL query string to delete the specified permissions for the role
 */
function buildPermissionDelete(
  role: string,
  permissions: Array<string>,
): string {
  const screenList = permissions.map((s) => `'${s}'`).join(', ');
  return `
    DELETE p
    FROM permission p
    INNER JOIN role r ON r.role_id = p.role_id
    WHERE r.role_name = '${role}'
      AND p.app_name IN (${screenList});
  `;
}

/**
 *
 * @param role role name
 * @param permissions list of app names (permissions) to insert for the role
 * @returns SQL query string to insert the specified permissions for the role
 */
function buildInsertPermissionQuery(
  role: string,
  permissions: Array<string>,
): string {
  if (permissions.length === 0) return '';
  const values = buildPermissionSelect(role, permissions);
  return `
    INSERT INTO permission (role_id, app_name, created_at, updated_at)
    ${values};
  `;
}

