        throw new NotFoundException(`AppRelease #${appId} not found`);
      }

      const updated = Object.assign(existing, data);
      return await this.appReleaseRepository.save(updated);
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to update AppRelease #${appId}`,
      );
    }
  }
