import {
  Injectable,
  NotFoundException,
  InternalServerErrorException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { NpsConfigRole } from '../nps-config-role/nps-config-role.entity';
import { NpsConfigResponseDto } from './dto/nps-config-response.dto';
import { NpsConfigListItem } from './dto/nps-item-list.dto';
import { NpsConfig } from './nps-config.entity';

type UpdateNpsConfigInput = Partial<NpsConfig> & {
  roleIds?: Array<number> | number;
};
@Injectable()
export class NpsConfigService {
  public constructor(
    @InjectRepository(NpsConfig)
    private readonly npsConfigRepository: Repository<NpsConfig>,

    @InjectRepository(NpsConfigRole)
    private readonly npsConfigRoleRepository: Repository<NpsConfigRole>,
  ) {}

  public async findAll(): Promise<Array<NpsConfigListItem>> {
    try {
      const rows = await this.npsConfigRepository.query(`WITH responses AS (
    SELECT
        r.nps_id,
        r.user_id,
        r.response_score
    FROM (
        SELECT
            r.nps_id,
            r.user_id,
            r.response_score,
            ROW_NUMBER() OVER (
                PARTITION BY r.nps_id, r.user_id, CONVERT(DATETIME2(0), r.updated_at)
                ORDER BY r.updated_at DESC
            ) AS rn
        FROM nps_response r
        WHERE r.response_type = 'SUBMITTED'
    ) r
    WHERE r.rn = 1
),
calculated_responses AS (
    SELECT
        nps_id,
        COUNT(*) AS total_responses,
        SUM(response_score) * 1.0 / COUNT(*) AS avg_score,
        COUNT(CASE WHEN response_score <= 6 THEN 1 END) AS detractors,
        COUNT(CASE WHEN response_score >= 9 THEN 1 END) AS promoters
    FROM responses
    GROUP BY nps_id
)
SELECT
    nc.nps_id AS "npsId",
    nc.is_active AS "isActive",
    nc.show_button AS "showButton",
    nc.comment_required AS "commentRequired",
    nc.trigger_type AS "triggerType",
    nc.trigger_delay_time AS "triggerDelayTime",
    nc.redisplay_interval AS "redisplayInterval",
    nc.behavior_dismissal AS "behaviorDismissal",
    nc.reprompt_day AS "repromptDay",
    ar.release_id AS "releaseId",
    ar.app_name AS "appName",
    ar.app_title AS "appTitle",
    COALESCE(calculated.avg_score, 0) AS "responseScore",
    COALESCE(calculated.total_responses, 0) AS "totalResponses",
    COALESCE(calculated.detractors, 0) AS "detractors",
    COALESCE(calculated.promoters, 0) AS "promoters"
FROM nps_config nc
LEFT JOIN app_release ar
    ON ar.app_id = nc.app_id
LEFT JOIN calculated_responses calculated
    ON calculated.nps_id = nc.nps_id;
`);
      return rows.map((row: Record<string, unknown>) => {
        const totalResponses = Number(row.totalResponses ?? 0);
        const detractors = Number(row.detractors ?? 0);
        const promoters = Number(row.promoters ?? 0);
        const npsScore =
          totalResponses === 0
            ? 0
            : Number(
                (((promoters - detractors) * 100) / totalResponses).toFixed(2),
              );
        return {
          appName: row.appName,
          appTitle: row.appTitle,
          behaviorDismissal: row.behaviorDismissal,
          commentRequired: row.commentRequired,
          isActive: row.isActive,
          npsId: row.npsId,
          npsScore,
          redisplayInterval: row.redisplayInterval,
          releaseId: row.releaseId,
          repromptDay: row.repromptDay,
          responseScore: Number(row.responseScore ?? 0),
          showButton: row.showButton,
          totalResponses,
          triggerDelayTime: row.triggerDelayTime,
          triggerType: row.triggerType,
        };
      });
    } catch {
      throw new InternalServerErrorException('Failed to retrieve NPS configs');
    }
  }

  public async findByRoleAndApp(
    roleNames: Array<string>,
    appName: string,
    userId: number,
  ): Promise<NpsConfigResponseDto | null> {
    try {
      const npsConfig = await this.npsConfigRepository
        .createQueryBuilder('config')

        .leftJoin('config.appId', 'appRelease')
        .leftJoin(
          'nps_config_role',
          'configRole',
          'configRole.nps_id = config.nps_id',
        )
        .leftJoin('role', 'role', 'role.role_id = configRole.role_id')
        .leftJoin(
          'nps_response',
          'response',
          'response.nps_id = config.nps_id AND response.user_id = :userId',
          { userId },
        )

        .leftJoin('config.npsEventTrigger', 'npsEventTrigger')

        .where('appRelease.appName = :appName', { appName })
        .andWhere('role.roleName IN (:...roleNames)', { roleNames })
        .orderBy('response.updated_at', 'DESC')

        .select([
          'config.npsId AS npsId',
          'config.isActive AS isActive',
          'config.showButton AS showButton',
          'config.commentRequired AS commentRequired',
          'config.triggerType AS triggerType',
          'config.triggerDelayTime AS triggerDelayTime',
          'config.redisplayInterval AS redisplayInterval',
          'config.behaviorDismissal AS behaviorDismissal',
          'config.repromptDay AS repromptDay ',
          'appRelease.releaseId AS releaseId',
          'appRelease.appName AS appName',
          'appRelease.appTitle AS appTitle',
          'npsEventTrigger.apiUrlPattern AS apiUrlPattern',
          'npsEventTrigger.eventName AS eventName',
          'response.updated_at AS updatedAt',
          'response.response_type AS responseType',
        ])
        .getRawOne();

      if (!npsConfig) {
        throw new NotFoundException(
          `No NPS config found for roles '${roleNames.join(', ')}' and app '${appName}'`,
        );
      }

      return npsConfig;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        'Failed to retrieve NPS config by role and app',
      );
    }
  }

  public async findOne(npsId: number): Promise<NpsConfigResponseDto> {
    try {
      const rows = await this.npsConfigRepository
        .createQueryBuilder('config')

        .leftJoin('config.appId', 'appRelease')
        .leftJoin(
          'nps_config_role',
          'configRole',
          'configRole.nps_id = config.nps_id',
        )
        .leftJoin('role', 'role', 'role.role_id = configRole.role_id')

        .leftJoin('config.npsEventTrigger', 'npsEventTrigger')

        .where('config.npsId = :npsId', { npsId })

        .select([
          'config.npsId AS npsId',
          'config.isActive AS isActive',
          'config.showButton AS showButton',
          'config.commentRequired AS commentRequired',
          'config.triggerType AS triggerType',
          'config.triggerDelayTime AS triggerDelayTime',
          'config.redisplayInterval AS redisplayInterval',
          'config.behaviorDismissal AS behaviorDismissal',
          'config.repromptDay AS repromptDay ',
          'appRelease.releaseId AS releaseId',
          'appRelease.appName AS appName',
          'appRelease.appTitle AS appTitle',
          'role.roleName AS roleName',
          'npsEventTrigger.apiUrlPattern AS apiUrlPattern',
          'npsEventTrigger.eventName AS eventName',
        ])
        .getRawMany();

      if (rows.length === 0) {
        throw new NotFoundException(`NpsConfig #${npsId} not found`);
      }

      const first = rows[0];
      return {
        ...first,
        roleNames: rows.map((row) => row.roleName as string).filter(Boolean),
      };
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to retrieve NpsConfig #${npsId}`,
      );
    }
  }

  public async create(data: NpsConfig): Promise<NpsConfig> {
    try {
      const entity = this.npsConfigRepository.create(data);
      return await this.npsConfigRepository.save(entity);
    } catch {
      throw new InternalServerErrorException('Failed to create NPS config');
    }
  }

  public async update(
    npsId: number,
    data: UpdateNpsConfigInput,
  ): Promise<NpsConfig> {
    try {
      const { roleIds, ...configData } = data;

      const existing = await this.npsConfigRepository.findOneBy({ npsId });

      if (!existing) {
        throw new NotFoundException(`NpsConfig #${npsId} not found`);
      }

      const updated = Object.assign(existing, configData);
      const savedConfig = await this.npsConfigRepository.save(updated);

      if (roleIds !== undefined && roleIds !== null) {
        const normalizedRoleIds = Array.isArray(roleIds) ? roleIds : [roleIds];
        const requestedRoleIds = new Set(
          normalizedRoleIds.filter(
            (roleId): roleId is number => typeof roleId === 'number',
          ),
        );

        const existingRoleRows = await this.npsConfigRoleRepository
          .createQueryBuilder('mapping')
          .select('mapping.role_id', 'roleId')
          .where('mapping.nps_id = :npsId', { npsId })
          .getRawMany<{ roleId: number }>();
        const existingRoleIds = new Set(
          existingRoleRows.map((row) => Number(row.roleId)),
        );

        const rolesToDelete = [...existingRoleIds].filter(
          (roleId) => !requestedRoleIds.has(roleId),
        );
        const rolesToAdd = [...requestedRoleIds].filter(
          (roleId) => !existingRoleIds.has(roleId),
        );

        if (rolesToDelete.length > 0) {
          await this.npsConfigRoleRepository
            .createQueryBuilder()
            .delete()
            .from(NpsConfigRole)
            .where('nps_id = :npsId', { npsId })
            .andWhere('role_id IN (:...rolesToDelete)', { rolesToDelete })
            .execute();
        }

        if (rolesToAdd.length > 0) {
          const newMappings = rolesToAdd.map((roleId) =>
            this.npsConfigRoleRepository.create({
              npsConfig: { npsId } as NpsConfig,
              role: { roleId },
            }),
          );

          await this.npsConfigRoleRepository.save(newMappings);
        }
      }

      return savedConfig;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to update NpsConfig #${npsId}`,
      );
    }
  }

  public async delete(npsId: number): Promise<void> {
    try {
      const result = await this.npsConfigRepository.delete(npsId);

      if (result.affected === 0) {
        throw new NotFoundException(`NpsConfig #${npsId} not found`);
      }
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to delete NpsConfig #${npsId}`,
      );
    }
  }
}

