@Injectable()
export class NpsEventTriggerService {
  public constructor(
    @InjectRepository(NpsEventTrigger)
    private readonly npsEventTriggerRepository: Repository<NpsEventTrigger>,
  ) {}

  public async findAll(): Promise<Array<NpsEventTrigger>> {
    try {
      return await this.npsEventTriggerRepository.find();
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve NPS event triggers',
      );
    }
  }

  public async findOne(npsEventTriggerId: number): Promise<NpsEventTrigger> {
    try {
      const entity = await this.npsEventTriggerRepository.findOneBy({
        npsEventTriggerId,
      });

      if (!entity) {
        throw new NotFoundException(
          `NpsEventTrigger #${npsEventTriggerId} not found`,
        );
      }

      return entity;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to retrieve NpsEventTrigger #${npsEventTriggerId}`,
      );
    }
  }

  public async create(
    data: Partial<NpsEventTrigger>,
  ): Promise<NpsEventTrigger> {
    try {
      const entity = this.npsEventTriggerRepository.create(data);
      return await this.npsEventTriggerRepository.save(entity);
    } catch {
      throw new InternalServerErrorException(
        'Failed to create NPS event trigger',
      );
    }
  }

  public async update(
    npsEventTriggerId: number,
    data: Partial<NpsEventTrigger>,
  ): Promise<NpsEventTrigger> {
    try {
      const existing = await this.npsEventTriggerRepository.findOneBy({
        npsEventTriggerId,
      });

      if (!existing) {
        throw new NotFoundException(
          `NpsEventTrigger #${npsEventTriggerId} not found`,
        );
      }

      const updated = Object.assign(existing, data);
      return await this.npsEventTriggerRepository.save(updated);
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to update NpsEventTrigger #${npsEventTriggerId}`,
      );
    }
  }

  public async delete(npsEventTriggerId: number): Promise<void> {
    try {
      const result =
        await this.npsEventTriggerRepository.delete(npsEventTriggerId);

      if (result.affected === 0) {
        throw new NotFoundException(
          `NpsEventTrigger #${npsEventTriggerId} not found`,
        );
      }
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to delete NpsEventTrigger #${npsEventTriggerId}`,
      );
    }
  }

  public async findByAppId(appId: number): Promise<Array<NpsEventTrigger>> {
    try {
      const response = await this.npsEventTriggerRepository
        .createQueryBuilder('npsEventTrigger')
        .innerJoinAndSelect('npsEventTrigger.appId', 'appRelease')
        .where('appRelease.appId = :appId', { appId })
        .select([
          'npsEventTrigger.npsEventTriggerId',
          'npsEventTrigger.apiUrlPattern',
          'npsEventTrigger.eventName',
        ])
        .getRawMany();
      return response;
    } catch {
      throw new InternalServerErrorException(
