import {
  BadRequestException,
  Injectable,
  NotFoundException,
  InternalServerErrorException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DeepPartial, In, Repository } from 'typeorm';
import { AppResponseDto } from './dto/app-response.dto';
import { NpsResponseParameterDto } from './dto/nps-response-parameter.dto';
import { NpsResponseRecordDto } from './dto/nps-response-record.dto';
import { NpsResponse } from './nps-response.entity';
import { Role } from '@/role/role.entity';

@Injectable()
export class NpsResponseService {
  public constructor(
    @InjectRepository(NpsResponse)
    private readonly npsResponseRepository: Repository<NpsResponse>,
    @InjectRepository(Role)
    private readonly roleRepository: Repository<Role>,
  ) {}

  public async findAll(): Promise<Array<NpsResponse>> {
    try {
      return await this.npsResponseRepository
        .createQueryBuilder('npsResponse')
        .leftJoinAndSelect('npsResponse.npsConfig', 'npsConfig')
        .leftJoinAndSelect('npsResponse.role', 'role')
        .leftJoinAndSelect('npsResponse.user', 'user')
        .getRawMany();
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve NPS responses',
      );
    }
  }

  public async findByNpsConfig(
    npsId: number,
  ): Promise<Array<NpsResponseRecordDto> | undefined> {
    try {
      const responses = await this.npsResponseRepository
        .createQueryBuilder('npsResponse')
        .leftJoinAndSelect('npsResponse.npsConfig', 'npsConfig')
        .leftJoinAndSelect('npsResponse.role', 'role')
        .leftJoinAndSelect('npsResponse.user', 'user')
        .where('npsConfig.npsId = :npsId', { npsId })
        .andWhere('npsResponse.responseType =:status', { status: 'SUBMITTED' })
        .select([
          'CONVERT(DATETIME2(0), npsResponse.updatedAt) AS lastUpdated',
          'npsResponse.responseType AS responseType',
          'npsResponse.responseScrore AS score',
          'npsResponse.responseComment As comment',
          'npsResponse.plant AS plant',
          'npsResponse.responseRelease As release',
          'role.roleName As roleName',
          'user.userId As userId',
          'user.firstName As firstName',
          'user.lastName As lastName',
        ])
        .getRawMany();
      const map = new Map<string, NpsResponseRecordDto>();

      for (const row of responses) {
        const key = [row.userId, row.lastUpdated, row.score, row.comment].join(
          '|',
        );

        let item = map.get(key);

        if (!item) {
          item = {
            comment: row.comment,
            firstName: row.firstName,
            lastName: row.lastName,
            lastUpdated: row.lastUpdated,
            plant: row.plant,
            release: row.release,
            responseType: row.responseType,
            roleName: [],
            score: row.score,
          };

          map.set(key, item);
        }

        item.roleName.push(row.roleName);
      }
      return [...map.values()];
    } catch {
      throw new InternalServerErrorException(
        `Failed to retrieve responses for NpsConfig #${npsId}`,
      );
    }
  }

  public async findOne(npsResponseId: number): Promise<NpsResponse> {
    try {
      const entity = await this.npsResponseRepository
        .createQueryBuilder('npsResponse')
        .leftJoinAndSelect('npsResponse.npsConfig', 'npsConfig')
        .leftJoinAndSelect('npsResponse.role', 'role')
        .leftJoinAndSelect('npsResponse.user', 'user')
        .where('npsResponse.npsResponseId = :npsResponseId', { npsResponseId })
        .select([
          'npsResponse.updatedAt AS lastUpdated',
          'npsResponse.responseType AS responseType',
          'npsResponse.responseScrore AS score',
          'npsResponse.responseComment As comment',
          'npsResponse.plant AS plant',
          'npsResponse.responseRelease As release',
          'role.roleName As roleName',
          'user.firstName As firstName',
          'user.lastName As lastName',
        ])
        .getRawOne();

      if (!entity) {
        throw new NotFoundException(`NpsResponse #${npsResponseId} not found`);
      }

      return entity;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to retrieve NpsResponse #${npsResponseId}`,
      );
    }
  }

  public async create(
    data: Partial<NpsResponseParameterDto>,
  ): Promise<Array<NpsResponse>> {
    try {
      const userId = Number(data.userId);
      const npsConfigId = Number(data.npsConfigId);

      let roleIds: Array<number> = [];

      const roles = await this.roleRepository.findBy({
        roleName: In(data.roleNames ?? []),
      });
      roleIds = roles.map((r) => r.roleId);
      if (!userId || !npsConfigId || roleIds.length === 0) {
        throw new BadRequestException(
          'userId, npsConfigId and at least one roleId or roleName are required',
        );
      }

      const savedResponses = await Promise.all(
        roleIds.map(async (roleId) => {
          const existing = await this.npsResponseRepository
            .createQueryBuilder('response')
            .leftJoinAndSelect('response.npsConfig', 'npsConfig')
            .leftJoinAndSelect('response.role', 'role')
            .leftJoinAndSelect('response.user', 'user')
            .where('response.responseRelease = :responseRelease', {
              responseRelease: data.responseRelease,
            })
            .andWhere('response.responseType = :responseType', {
              responseType: 'DISMISSED',
            })
            .andWhere('user.userId = :userId', {
              userId,
            })
            .andWhere('npsConfig.npsId = :npsConfigId', {
              npsConfigId,
            })
            .andWhere('role.roleId = :roleId', {
              roleId,
            })
            .getOne();

          const payload: DeepPartial<NpsResponse> = {
            npsConfig: { npsId: npsConfigId },
            plant: data.plant,
            responseComment: data.comment,
            responseRelease: data.responseRelease,
            responseScrore: data.score,
            responseType: data.responseType,
            role: { roleId },
            user: { userId },
          };

          if (existing) {
            const updated = Object.assign(existing, payload);
            await this.npsResponseRepository
              .createQueryBuilder()
              .update()
              .set({
                ...payload,
                updatedAt: () => 'CURRENT_TIMESTAMP',
              })
              .where('npsResponseId = :id', { id: existing.npsResponseId })
              .execute();

            return updated;
          }

          const entity = this.npsResponseRepository.create(payload);
          return this.npsResponseRepository.save(entity);
        }),
      );

      return savedResponses;
    } catch (error) {
      if (error instanceof BadRequestException) throw error;
      throw new InternalServerErrorException('Failed to create NPS response');
    }
  }

  public async update(
    npsResponseId: number,
    data: Partial<NpsResponse>,
  ): Promise<NpsResponse> {
    try {
      const existing = await this.npsResponseRepository.findOneBy({
        npsResponseId,
      });

      if (!existing) {
        throw new NotFoundException(`NpsResponse ${npsResponseId} not found`);
      }

      const updated = Object.assign(existing, data);
      return await this.npsResponseRepository.save(updated);
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to update NpsResponse #${npsResponseId}`,
      );
    }
  }

  public async delete(npsResponseId: number): Promise<void> {
    try {
      const result = await this.npsResponseRepository.delete(npsResponseId);

      if (result.affected === 0) {
        throw new NotFoundException(`NpsResponse #${npsResponseId} not found`);
      }
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new InternalServerErrorException(
        `Failed to delete NpsResponse ${npsResponseId}`,
      );
    }
  }

  public async getCommentBynpsId(
    npsId: number,
  ): Promise<Array<AppResponseDto>> {
    try {
      const responses = await this.npsResponseRepository
        .createQueryBuilder('npsResponse')
        .leftJoinAndSelect('npsResponse.npsConfig', 'npsConfig')
        .leftJoinAndSelect('npsResponse.role', 'role')
        .leftJoinAndSelect('npsResponse.user', 'user')
        .where('npsConfig.npsId = :npsId', { npsId })
        .andWhere('npsResponse.responseType =:status', { status: 'SUBMITTED' })
        .select([
          'npsResponse.updatedAt AS lastUpdated',
          'npsResponse.responseComment As comment',
          'npsResponse.responseRelease As release',
          'npsResponse.plant AS plant',
          'role.roleName As roleName',
          'user.firstName As firstName',
          'user.lastName As lastName',
        ])
        .getRawMany();
      const map = new Map<string, AppResponseDto>();

      for (const row of responses) {
        const key = [row.userId, row.lastUpdated, row.comment].join('|');

        let item = map.get(key);

        if (!item) {
          item = {
            comment: row.comment,
            firstName: row.firstName,
            lastName: row.lastName,
            lastUpdated: row.lastUpdated,
            plant: row.plant,
            release: row.release,
            roleName: [],
          };

          map.set(key, item);
        }

        item.roleName.push(row.roleName);
      }

      return [...map.values()];
    } catch {
      throw new InternalServerErrorException(
        `Failed to retrieve responses for NpsConfig #${npsId}`,
      );
    }
  }

  public async getScoreBynpsId(npsId: number): Promise<{
    totalResponses: number;
    detractors: number;
    passives: number;
    promoters: number;
    npsScore: number;
  }> {
    try {
      const [result] = await this.npsResponseRepository.query(
        `SELECT
          COUNT(*) AS totalResponses,
          SUM(CASE WHEN v.response_score BETWEEN 0 AND 6 THEN 1 ELSE 0 END) AS detractors,
          SUM(CASE WHEN v.response_score BETWEEN 7 AND 8 THEN 1 ELSE 0 END) AS passives,
          SUM(CASE WHEN v.response_score BETWEEN 9 AND 10 THEN 1 ELSE 0 END) AS promoters
        FROM (
          SELECT
            v.nps_id,
            v.user_id,
            v.response_score
          FROM (
            SELECT
              response.nps_id,
              response.user_id,
              response.response_score,
              ROW_NUMBER() OVER (
                PARTITION BY response.nps_id, response.user_id, CONVERT(DATETIME2(0), response.updated_at)
                ORDER BY response.updated_at DESC
              ) AS rn
            FROM nps_response response
            WHERE response.nps_id = @0 AND response.response_type = @1
          ) v
          WHERE v.rn = 1
        ) v`,
        [npsId, 'SUBMITTED'],
      );

      const totalResponses = Number(result?.totalResponses ?? 0);
      const detractors = Number(result?.detractors ?? 0);
      const passives = Number(result?.passives ?? 0);
      const promoters = Number(result?.promoters ?? 0);
      const npsScore =
        totalResponses === 0
          ? 0
          : Number(
              (((promoters - detractors) * 100) / totalResponses).toFixed(2),
            );

      return {
        detractors,
        npsScore,
        passives,
        promoters,
        totalResponses,
      };
    } catch {
      throw new InternalServerErrorException(
        `Failed to retrieve responses for NpsConfig #${npsId}`,
      );
    }
  }
}

