import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PermissionDefinition } from './permission-definition.entity';

@Injectable()
export class PermissionDefinitionService {
  public constructor(
    @InjectRepository(PermissionDefinition)
    private readonly permissionDeferredRepository: Repository<PermissionDefinition>,
  ) {}

  public async getPermissionsByRole(
    appName: string,
    roleNames: string,
  ): Promise<Array<PermissionDefinition>> {
    const roleNamesArray = roleNames.split(',');

    // Fetching permissions from the database
    const permissions = await this.permissionDeferredRepository
      .createQueryBuilder('pd')
      .innerJoin('permission', 'p', 'pd.permission_id = p.permission_id')
      .innerJoin('role', 'r', 'p.role_id = r.role_id')
      .where('p.app_name = :appName', { appName })
      .andWhere('r.role_name IN (:...roleNames)', { roleNames: roleNamesArray })
      .select(['pd.object', 'pd.actionType'])
      .getMany();

    // Creating a map to store unique objects with prioritized 'enable' actionType
    const uniquePermissionsMap = new Map<string, PermissionDefinition>();

    // Process permissions to prioritize 'enable' over 'disable'
    for (const permission of permissions) {
      const objectName = permission.object;

      // If the object doesn't exist in the map, add it
      if (uniquePermissionsMap.has(objectName)) {
        const existingPermission = uniquePermissionsMap.get(objectName);

        // If the existing permission is 'disable' and the new one is 'enable', prioritize 'enable'
        if (
          existingPermission &&
          existingPermission.actionType === 'disable' &&
          permission.actionType === 'enable'
        ) {
          uniquePermissionsMap.set(objectName, permission);
        }
      } else {
        uniquePermissionsMap.set(objectName, permission);
      }
    }

    // Return the values from the map as an array
    return [...uniquePermissionsMap.values()];
  }
}

