import { Injectable, UnauthorizedException } from '@nestjs/common';
import axios from 'axios-https-proxy-fix';
import * as jwt from 'jsonwebtoken';
import * as jwkToPem from 'jwk-to-pem';
import { AppLogger } from 'src/common/logger/app-logger';

@Injectable()
export class TokenValidationService {
  private readonly logger = new AppLogger(TokenValidationService.name);

  private readonly urlApi = process.env.ENTRA_PUBLIC_KEY_ENDPOINT;

  private readonly proxyHost =
    process.env.PROXY_HOST ?? 'cloudproxy.standard.corp';

  private readonly proxyPort = process.env.PROXY_PORT ?? '8080';

  public async fetchAndSetPublicKeys(): Promise<any> {
    if (!this.urlApi || !this.proxyHost) {
      throw new Error('environment variable is not defined');
    }
    if (!this.proxyPort) {
      throw new Error('proxyPort environment variable is not defined');
    }
    try {
      const response = await axios.get(this.urlApi, {
        proxy: {
          host: this.proxyHost,
          port: Number.parseInt(this.proxyPort, 10),
        },
      });

      const { keys } = response.data;
      const firstKey = keys[0];
      return firstKey;
    } catch (error) {
      this.logger.error('error');
      throw error;
    }
  }

  public async validateToken(token: string): Promise<unknown> {
    try {
      const firstKey = await this.fetchAndSetPublicKeys();
      if (!firstKey) {
        throw new Error('Public key not available');
      }
      const publicKeyPem = jwkToPem(firstKey);
      const decodedToken = jwt.verify(token, publicKeyPem, {
        algorithms: ['RS256'],
      }) as jwt.JwtPayload;

      if (decodedToken.exp && Date.now() >= decodedToken.exp * 1000) {
        throw new Error('Token expired');
      }

      return decodedToken;
    } catch (error) {
      this.logger.error(error);
      throw new UnauthorizedException('Invalid token');
    }
  }
}

