import { HttpMethod } from '@dapr/dapr';
import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DaprClient } from 'dapr-client';
import { Repository, In } from 'typeorm';
import { User } from '../user/user.entity';
import { UserAttributeMapping } from './user-attribute-mapping.entity';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { GetUserAttributeDto } from '@/dto/get-user-attribute.dto';
import { Plant } from '@/dto/plant-type';

interface UserDetail {
  userId: number;
}

interface UserAttribute {
  userAttributeId: number;
}

@Injectable()
export class UserAttributeMappingService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(UserAttributeMappingService.name);

  public constructor(
    @InjectRepository(UserAttributeMapping)
    private readonly userAttributeMappingRepository: Repository<UserAttributeMapping>,
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly daprConfigService: DaprConfigService,
  ) {
    this.daprClient = new DaprClient();
  }

  public async getUserByPlant(
    value: string,
  ): Promise<Array<{ firstName: string; lastName: string }> | null> {
    const userAttributeMappings =
      await this.userAttributeMappingRepository.find({
        where: { value },
        relations: ['user'],
      });

    if (!userAttributeMappings || userAttributeMappings.length === 0) {
      return null;
    }

    const userIds = userAttributeMappings.map((mapping) => mapping.user.userId);
    const users = await this.userRepository.find({
      where: { userId: In(userIds) },
    });
    return users.map((user) => ({
      userId: user.userId,
      firstName: user.firstName,
      lastName: user.lastName,
    }));
  }

  public async saveCustomAttributes(
    userId: number,
    userAttributes: Array<{ userAttributeId: number; value: string }>,
  ): Promise<{ status: string; message: string }> {
    if (userAttributes.length === 0) {
      throw new InternalServerErrorException('No user attributes provided');
    }
    try {
      const savePromises = userAttributes.map(async (attribute) => {
        let attributeMapping =
          await this.userAttributeMappingRepository.findOne({
            where: {
              user: { userId } as UserDetail,
              userAttribute: {
                userAttributeId: attribute.userAttributeId,
              } as UserAttribute,
            },
          });

        if (attributeMapping) {
          attributeMapping.value = attribute.value;
        } else {
          attributeMapping = this.userAttributeMappingRepository.create({
            user: { userId } as UserDetail,
            userAttribute: {
              userAttributeId: attribute.userAttributeId,
            } as UserAttribute,
            value: attribute.value,
          });
        }

        try {
          await this.userAttributeMappingRepository.save(attributeMapping);
          return true;
        } catch (error) {
          console.error(
            `Failed to save custom attribute for userAttributeId ${attribute.userAttributeId}: ${error.message}`,
          );
          return false;
        }
      });
      const saveResults = await Promise.all(savePromises);
      const saveCount = saveResults.filter(Boolean).length;
      if (saveCount === 0) {
        throw new InternalServerErrorException(
          'Failed to save any custom attributes.',
        );
      }
      return {
        message: `${saveCount} custom attribute(s) saved successfully.`,
        status: 'success',
      };
    } catch (error) {
      console.error(`Failed to save custom attributes: ${error.message}`);
      throw new InternalServerErrorException(
        'Failed to save custom attributes.',
      );
    }
  }

  public async deleteUserAttributes(
    userId: number,
    userAttributeIds: Array<number>,
  ): Promise<{ status: string; message: string }> {
    if (userAttributeIds.length === 0) {
      throw new BadRequestException('No user attribute IDs provided');
    }

    try {
      const deletePromises = [];
      for (const userAttributeId of userAttributeIds) {
        deletePromises.push(
          this.userAttributeMappingRepository.delete({
            user: { userId } as UserDetail,
            userAttribute: { userAttributeId } as UserAttribute,
          }),
        );
      }

      await Promise.all(deletePromises);

      const deleteCount = deletePromises.length;

      if (deleteCount === 0) {
        throw new NotFoundException('None of the custom attributes were found');
      }

      return {
        message: `${deleteCount} custom attribute(s) deleted successfully.`,
        status: 'success',
      };
    } catch (error) {
      console.error(`Failed to delete custom attributes: ${error.message}`);
      throw new NotFoundException('Failed to delete custom attributes.');
    }
  }

  public async getTimeZonebyId(id: number): Promise<string> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethodPlant = `plant/getPlantById/${id}`;
    const response = (await this.daprClient.invoker
      .invoke(serviceAppId, serviceMethodPlant, HttpMethod.GET)
      .catch((error) => {
        this.logger.error(error);
      })) as Plant;
    const timezone = response.timezone ?? ('utc' as string);
    return timezone;
  }

  public async findByUserId(
    userId: number,
  ): Promise<Array<{ value: string; userAttributeName: string }>> {
    const mappings = await this.userAttributeMappingRepository
      .createQueryBuilder('mapping')
      .select(['userAttribute.userAttributeName', 'mapping.value'])
      .innerJoin('mapping.userAttribute', 'userAttribute')
      .where('mapping.user.userId = :userId', { userId })
      .getMany();

    const plantMapping = mappings.find(
      (mapping) => mapping.userAttribute.userAttributeName === 'plant',
    );

    if (!plantMapping) {
      throw new NotFoundException('Plant attribute not found for user');
    }

    const timezone = await this.getTimeZonebyId(Number(plantMapping.value));
    const result = mappings.map((mapping) => ({
      userAttributeName: mapping.userAttribute.userAttributeName,
      value: mapping.value,
    }));

    result.push({
      userAttributeName: 'timezone',
      value: timezone,
    });

    return result;
  }

  public async getUserAttributeIdNameAndValue(
    userId: number,
  ): Promise<Array<GetUserAttributeDto>> {
    const mappings = await this.userAttributeMappingRepository
      .createQueryBuilder('mapping')
      .select([
        'userAttribute.userAttributeId',
        'userAttribute.userAttributeName',
        'mapping.value',
      ])
      .innerJoin('mapping.userAttribute', 'userAttribute')
      .where('mapping.user.userId = :userId', { userId })
      .getMany();

    return mappings.map((mapping) => ({
      userAttributeId: mapping.userAttribute.userAttributeId,
      userAttributeName: mapping.userAttribute.userAttributeName,
      value: mapping.value,
    }));
  }

  public async getPlantByEmail(email: string): Promise<string | null> {
    try {
      const mapping = await this.userAttributeMappingRepository
        .createQueryBuilder('mapping')
        .innerJoin('mapping.user', 'u')
        .innerJoin('mapping.userAttribute', 'attribute')
        .select('mapping.value', 'value')
        .where('u.email = :email', { email })
        .andWhere('attribute.userAttributeName = :attr', { attr: 'plant' }) // Exact column value
        .getRawOne<{ value: string }>();

      return mapping?.value ?? null;
    } catch (error) {
      console.error('Error in getPlantByEmail:', error);
      return null;
    }
  }
}

