@Injectable()
export class UserPreferenceService {
  private static mapToUserPreferenceResponseDto(
    entity: UserPreference,
  ): UserPreferenceResponseDto {
    const dto = new UserPreferenceResponseDto();
    dto.action = entity.action;
    dto.addData = entity.addData;
    dto.appName = entity.appName;
    dto.object = entity.object;
    dto.plant = entity.plant;
    dto.userCriteria = entity.userCriteria;
    return dto;
  }

