    private readonly userPreferenceRepository: Repository<UserPreference>,
  ) {}

  public async getUserPreferenceByPlantUserIdAndAppName(
    plant: number,
    userId: number,
    appName: string,
  ): Promise<Array<CreateUserPreferenceDto>> {
    const userPreference = await this.userPreferenceRepository.find({
      where: { plant, user: { userId }, appName },
    });

    if (userPreference && userPreference.length > 0) {
      return userPreference;
    }
    return [];
  }

  public async saveUserPreferences(
    createUserPreferenceDtoList: Array<UserPreference>,
  ): Promise<Array<UserPreference>> {
    if (!Array.isArray(createUserPreferenceDtoList)) {
      throw new TypeError('Input must be an array.');
    }
    // Iterate over the list of preferences and handle each one
    const savedPreferences: Array<UserPreference> = [];
    await Promise.all(
      createUserPreferenceDtoList.map(async (createUserPreferenceDto) => {
        // Check if user preferences already exist for the given appName
        const existingPreferences =
          await this.getUserPreferenceByPlantUserIdAndAppName(
            createUserPreferenceDto.plant,
            createUserPreferenceDto.user.userId, // Assuming userId is available in the DTO
            createUserPreferenceDto.appName,
          );

        // Filter existing preferences based on action and object
        const hideColPreferences = existingPreferences.filter(
          (preference) => preference.action === 'HIDE_COL',
        );
        const filterPreferences = existingPreferences.filter(
          (preference) => preference.action === 'FILTER',
        );

        // Check if there's a preference to hide columns
        if (createUserPreferenceDto.action === 'HIDE_COL') {
          // If there are existing hide column preferences, update the first one
          if (hideColPreferences.length > 0) {
            const existingHideColPreference = hideColPreferences[0]; // Assuming there's only one hide column preference per appName
            existingHideColPreference.addData = createUserPreferenceDto.addData;
            const updatedPreference = await this.userPreferenceRepository.save(
              existingHideColPreference,
            );
            savedPreferences.push(updatedPreference);
          } else {
            // If there's no existing hide column preference, create a new one
            const newPreference = this.userPreferenceRepository.create(
              createUserPreferenceDto,
            );
            const savedPreference =
              await this.userPreferenceRepository.save(newPreference);
            savedPreferences.push(savedPreference);
          }
        }

        // Check if there's a preference to filter
        if (createUserPreferenceDto.action === 'FILTER') {
          // If there's an existing filter preference for the same object, update it
          const existingFilterPreference = filterPreferences.find(
            (preference) =>
              preference.object === createUserPreferenceDto.object,
          );
          if (existingFilterPreference) {
            existingFilterPreference.addData = createUserPreferenceDto.addData;
            const updatedPreference = await this.userPreferenceRepository.save(
              existingFilterPreference,
            );
            savedPreferences.push(updatedPreference);
          } else {
            // If there's no existing filter preference for the same object, create a new one
            const newPreference = this.userPreferenceRepository.create(
              createUserPreferenceDto,
            );
            const savedPreference =
              await this.userPreferenceRepository.save(newPreference);
            savedPreferences.push(savedPreference);
          }
        }
      }),
    );
    return savedPreferences;
  }

  public async fetchUserPreferenceByPlantUserIdAndAppName(
    plant: number,
    userId: number,
    appName: string,
  ): Promise<Array<UserPreferenceResponseDto>> {
    const userPreferenceEntities = await this.userPreferenceRepository.find({
      relations: ['user'],
      where: { appName, plant, user: { userId } },
    });
    return userPreferenceEntities.map((entity) =>
      UserPreferenceService.mapToUserPreferenceResponseDto(entity),
    );
  }

  public async addUserPreferences(
    createUserPreferenceDtoList:
      | Array<UserPreferenceResponseDto>
      | UserPreferenceResponseDto,
  ): Promise<string> {
    const preferencesArray = Array.isArray(createUserPreferenceDtoList)
      ? createUserPreferenceDtoList
      : [createUserPreferenceDtoList];
    await Promise.all(
      preferencesArray.map(async (dto) => {
        const existingPreferences =
          await this.fetchUserPreferenceByPlantUserIdAndAppName(
            dto.plant,
            dto.user.userId,
            dto.appName,
          );

        if (existingPreferences && existingPreferences.length > 0) {
          // Access the first preference from the array
          const existingPreference = existingPreferences[0];
          existingPreference.userCriteria = dto.userCriteria;
          const { plant, appName } = existingPreference;
          await this.userPreferenceRepository.update(
            { appName, plant, user: { userId: dto.user.userId } },
            { userCriteria: dto.userCriteria },
          );
        } else {
          const newPreference = this.userPreferenceRepository.create({
            action: dto.action,
            appName: dto.appName,
            plant: dto.plant,
            user: dto.user,
            userCriteria: dto.userCriteria,
          });
          await this.userPreferenceRepository.save(newPreference);
        }
      }),
    );

    return 'User preferences inserted successfully';
  }
}

import { Controller, Post, Body, Get, Param, Put } from '@nestjs/common';
import {
  ApiBadRequestResponse,
  ApiBody,
  ApiCreatedResponse,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';
import { CreateUserDto } from '../dto/create-user.dto';
import { User } from './user.entity';
import { UserService } from './user.service';

@ApiTags('users')
@Controller('users')
export class UserController {
  public constructor(private readonly userService: UserService) {}

  @ApiCreatedResponse({
    description: 'The user has been successfully created.',
  })
  @ApiBadRequestResponse({
    description: 'Bad request. Please check your request data.',
  })
  @Post()
  public async createUser(@Body() createUserDto: CreateUserDto): Promise<User> {
    return this.userService.createUser(createUserDto);
  }

  @Get('email/:email')
  @ApiOkResponse({
    description: 'User found',
    type: User,
  })
  @ApiParam({
    name: 'email',
    description: 'Email address of the user',
    type: String,
  })
  public async getUserByEmail(
    @Param('email') email: string,
  ): Promise<User | undefined> {
    return this.userService.getUserByEmail(email);
  }

  // eslint-disable-next-line no-console
  @Put(':email/last-login')
  @ApiOperation({ summary: 'Update user last login' })
  @ApiParam({ name: 'email', description: 'User email', type: 'string' })
  @ApiBody({ description: 'Last login date', type: Date })
  @ApiResponse({
    status: 200,
    description: 'User last login updated successfully',
  })
  @ApiResponse({ status: 404, description: 'User not found' })
  @ApiResponse({ status: 500, description: 'Failed to update user last login' })
  public async updateUserLastLoginByEmail(
    @Param('email') email: string,
    @Body('lastLogin') lastLogin: Date,
  ): Promise<string> {
    try {
      const result = await this.userService.updateUserLastLogin(
        email,
        lastLogin,
      );
      return result; // Return the result from the service method
    } catch {
      return 'Failed to update user last login';
    }
  }
}

import { UserPreference } from 'src/user-preference/user-preference.entity';
import { Entity, Column, PrimaryGeneratedColumn, OneToMany } from 'typeorm';
import { TimeStamp } from '@/Generics/timestamp';
import { HomepageShortcut } from '@/homepage-shortcuts/entities/homepage-shortcut.entity';
import { UserAttributeMapping } from '@/user-attribute-mapping/user-attribute-mapping.entity';

@Entity('users')
export class User extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'user_id' })
  public userId: number;

  @Column({ name: 'first_name', length: 50 })
  public firstName: string;

  @Column({ name: 'last_name', length: 50 })
  public lastName: string;

  @Column({ name: 'email', length: 100, unique: true })
  public email: string;

  @Column({ name: 'last_login' })
  public lastLogin: Date;

  @OneToMany(() => UserPreference, (userPreference) => userPreference.user)
  public preferences: Array<UserPreference>;

  @OneToMany(
    () => UserAttributeMapping,
    (userToUserAttribute) => userToUserAttribute.user,
  )
  public userToUserAttribute: Array<UserAttributeMapping>;

  @OneToMany(() => HomepageShortcut, (shortcut) => shortcut.user)
  public shortcuts: Array<HomepageShortcut>;
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { User } from './user.entity';
import { UserService } from './user.service';

@Module({
  imports: [TypeOrmModule.forFeature([User])],
  providers: [UserService],
  exports: [TypeOrmModule.forFeature([User]), UserService],
})
export class UserModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateUserDto } from '../dto/create-user.dto';
import { User } from './user.entity';

@Injectable()
export class UserService {
  public constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  public async createUser(userData: CreateUserDto): Promise<User> {
    const newUser = this.userRepository.create(userData);
    return this.userRepository.save(newUser);
  }

  public async getUserByEmail(email: string): Promise<User | undefined> {
    const user = await this.userRepository.findOne({ where: { email } });
    if (!user) {
      return undefined;
    }
    return user;
  }

  public async updateUserLastLogin(
    email: string,
    lastLogin: Date,
  ): Promise<string> {
    try {
      const user = await this.getUserByEmail(email);
      if (!user) {
        throw new NotFoundException(`User with email ${email} not found`);
      }
      user.lastLogin = lastLogin;
      await this.userRepository.save(user);
      return 'User last login updated successfully';
    } catch {
      return 'Failed to update user last login';
    }
  }
}

